plugins { antlr }

fun browserGrammarSource(source: String): String =
    "// @ts-nocheck -- generated by ANTLR, verified by contract tests\n" +
        source.replace(Regex("(\\\"\\./Calculation[^\\\"]*)\\.js\\\""), "$1.ts\"")

// Gradle's ANTLR plugin adds its compiler to api by default. Ship only the runtime.
configurations.api { setExtendsFrom(extendsFrom.filterNot { it.name == "antlr" }) }

dependencies {
    antlr("org.antlr:antlr4:4.13.2")
    implementation("org.antlr:antlr4-runtime:4.13.2")
}

tasks.generateGrammarSource {
    arguments = arguments + listOf("-visitor", "-no-listener", "-package", "org.simplepoint.calculation.grammar")
}

// The same grammar can be embedded in a browser without a server or platform client.
tasks.register<JavaExec>("generateTypeScriptGrammar") {
    classpath = configurations.antlr.get()
    mainClass.set("org.antlr.v4.Tool")
    val grammar = file("src/main/antlr/Calculation.g4")
    val output = rootProject.file("simplepoint-react/libs/calculation/src/generated")
    inputs.file(grammar)
    outputs.dir(output)
    workingDir(grammar.parentFile)
    args("-Dlanguage=TypeScript", "-visitor", "-no-listener", "-Xexact-output-dir", "-o", output, grammar.name)
    doLast {
        output.listFiles()?.forEach { generated ->
            if (generated.extension == "ts") {
                // ANTLR's generated imports target emitted JS; source exports also support bundlers.
                generated.writeText(browserGrammarSource(generated.readText()))
            } else generated.delete()
        }
    }
}

tasks.register<JavaExec>("verifyTypeScriptGrammar") {
    classpath = configurations.antlr.get()
    mainClass.set("org.antlr.v4.Tool")
    val grammar = file("src/main/antlr/Calculation.g4")
    val candidate = layout.buildDirectory.dir("verified-browser-grammar").get().asFile
    val checkedIn = rootProject.file("simplepoint-react/libs/calculation/src/generated")
    workingDir(grammar.parentFile)
    args("-Dlanguage=TypeScript", "-visitor", "-no-listener", "-Xexact-output-dir", "-o", candidate, grammar.name)
    doLast {
        val files = candidate.listFiles()!!.filter { it.extension == "ts" }
        check(files.map { it.name }.toSet() == checkedIn.listFiles()!!.filter { it.extension == "ts" }.map { it.name }.toSet())
        files.forEach { generated ->
            check(browserGrammarSource(generated.readText()) == checkedIn.resolve(generated.name).readText()) {
                "Browser grammar drift: run :simplepoint-calculation:generateTypeScriptGrammar"
            }
        }
    }
}

tasks.register("verifyStandaloneDependencies") {
    doLast {
        val artifacts = configurations.runtimeClasspath.get().resolvedConfiguration.resolvedArtifacts
        check(artifacts.size == 1 && artifacts.single().moduleVersion.id.let {
            it.group == "org.antlr" && it.name == "antlr4-runtime"
        }) {
            "The standalone calculation engine must not depend on platform, Spring, persistence or web libraries"
        }
    }
}
tasks.named("check") { dependsOn("verifyStandaloneDependencies", "verifyTypeScriptGrammar") }

// ANTLR owns generated formatting. All authored engine sources retain the platform quality gate.
tasks.named<Checkstyle>("checkstyleMain") { setSource(fileTree("src/main/java")) }
